CREATE OR REPLACE FUNCTION public.record_journey_event(p_event text,p_path text,p_session uuid,p_reason text,p_notice text,p_consent uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF p_event NOT IN ('page_view','cart_added','cart_removed','checkout_started','checkout_redirected','checkout_error','signup_error','signin_error','signup_submitted') OR p_path IS NULL OR p_session IS NULL OR p_consent IS NULL OR p_notice IS DISTINCT FROM 'journey-2026-10-30' OR length(p_path)>300 OR NOT (p_path='/' OR p_path ~ '^/(courses|cart|for-businesses|certificates|pricing|career|sign-in|sign-up|forgot-password|dashboard|verify|jobs|instructors|paths|help|trust|blog|contact|about|locations|faq|testimonials|bookmarks|account|support|refer|search|cohorts|bootcamp|terms|privacy|refund-policy|cookie-policy)$' OR p_path ~ '^/(courses|instructors|jobs|paths|help|blog|locations|category|p)/[a-zA-Z0-9_-]+(/(learn|quizzes|assignments|related))?$' OR p_path IN ('/orders/:id','/support/:id','/cohorts/:id','/verify/:code','/quizzes/:id/attempts')) THEN RAISE EXCEPTION 'Invalid journey event'; END IF;
IF p_reason IS NOT NULL AND p_reason NOT IN ('validation','authentication','payment_setup','payment_verification') THEN RAISE EXCEPTION 'Invalid reason'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.journey_choices c WHERE c.id=p_consent AND c.accepted AND c.notice_version=p_notice AND NOT EXISTS(SELECT 1 FROM public.journey_choices n WHERE n.visitor_id=c.visitor_id AND n.created_at>c.created_at)) THEN RETURN; END IF;
IF (SELECT count(*) FROM public.journey_events WHERE session_id=p_session AND created_at>now()-interval '1 minute')>=60 THEN RETURN; END IF;
INSERT INTO public.journey_events(user_id,session_id,consent_id,event,path,reason) VALUES(auth.uid(),p_session,p_consent,p_event,p_path,p_reason);
END $$;
REVOKE ALL ON FUNCTION public.record_journey_event(text,text,uuid,text,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_journey_event(text,text,uuid,text,text,uuid) TO anon,authenticated;